"""Minimum Falling Path Sum — row-by-row DP over three predecessors.

Time: O(n^2)   Space: O(n)
"""
from typing import List


class Solution:
    def minFallingPathSum(self, matrix: List[List[int]]) -> int:
        n = len(matrix)
        row = matrix[0][:]
        for i in range(1, n):
            nxt = []
            for j in range(n):
                best = min(row[max(0, j - 1):min(n, j + 2)])
                nxt.append(matrix[i][j] + best)
            row = nxt
        return min(row)
